import { useState } from "react";
import { Calendar } from "@godxjp/ui/data-entry";
import { ja } from "react-day-picker/locale";

// --- Single-date example (controlled) ---
export function InvoiceDateCalendar() {
  const [date, setDate] = useState<Date | undefined>(new Date());

  return (
    <Calendar
      mode="single"
      selected={date}
      onSelect={setDate}
      locale={ja}
      disabled={{ before: new Date(2024, 0, 1) }}
      footer={date ? `選択日: ${date.toLocaleDateString("ja-JP")}` : "日付を選択してください"}
      aria-label="発行日カレンダー"
    />
  );
}

// --- Range example inside a Popover (mirrors DatePicker range internals) ---
import { Popover, PopoverContent, PopoverTrigger } from "@godxjp/ui/data-display";
import { Button } from "@godxjp/ui/general";
import type { DateRange } from "react-day-picker";

export function ReportRangeFilter() {
  const [range, setRange] = useState<DateRange | undefined>();

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline">期間を選択</Button>
      </PopoverTrigger>
      {/* flush drops the panel's padding and width="auto" lets the calendar set the measure —
          the panel's own 18rem would clip two months. Never a w-auto/p-0 utility on className:
          those are per-call-site constants no service theme can retune. */}
      <PopoverContent flush width="auto" align="end">
        <Calendar
          mode="range"
          selected={range}
          onSelect={setRange}
          locale={ja}
          numberOfMonths={2}
          disabled={{ after: new Date() }}
          autoFocus
        />
      </PopoverContent>
    </Popover>
  );
}
